    dragPreviewState.rng.vassalSeed += 1;
    c.mutantRaw = JSON.stringify(dragPreviewState);
    c.mutations++;
  }
  const rawBefore = JSON.stringify({cursorState, dragPreviewState, timeline});

  const inspect2 = (state) => state == null ? null : {
    rawJson: JSON.stringify(state),
    stateData: serializeGameState(state)
  };
  const inspected = {
    version: 1,
    cursor: inspect2(cursorState),
    preview: inspect2(dragPreviewState),
    frontierSec: timeline?.historyEndSec ?? null,
    cursorIsFrontier: cursorState != null && cursorState.tSec === timeline?.historyEndSec,
